+/// The program's G32 blocks' Z words, in order.
+fn g32_zs(text: &str) -> Vec<f64> {
+    text.lines()
+        .filter(|l| l.starts_with("G32 "))
+        .filter_map(|l| l.split_whitespace().find_map(|w| w.strip_prefix('Z')).and_then(|z| z.parse().ok()))
+        .collect()
+}
